CIVILIZATION = "Атлантическая Коренная Цивилизация"
YEAR = "1200 г. н.э." # Предполагаемый год пересечения
TECHNOLOGY = "Передовая навигация, кораблестроение, знание морских течений"
REASONS = "Поиск новых земель, избежание перенаселения, религиозные миссии"
INITIAL_POPULATION = "5000 - 10000 человек"
PRIMARY_CULTURE = "Основана на принципах гармонии с природой, коллективизме и духовности"
INITIAL_LOCATION = "Восточное побережье Северной Америки (например, современные штаты Нью-Йорк, Нью-Джерси, Коннектикут)"
PRIMARY_TRADE_ROUTES = "Северная Атлантика, с остановками в Исландии, Шотландии, Ирландии, и возможно, в Западной Европе"
POTENTIAL_CONSEQUENCES = "Сложные и многогранные, с долгосрочными последствиями для всего мира"

# Цели Makefile
all: scenario

scenario:
