	@echo "Потенциальные последствия: $(POTENTIAL_CONSEQUENCES)"

# Подцелы для более детального анализа (можно расширить)
detailed_navigation:
	@echo "Детальное изучение навигации: Использование звезд, приливов, ветра, и знание океанских течений, возможно, с использованием примитивных, но эффективных карт и моделей."

detailed_culture:
	@echo "Детальное изучение культуры:  Сохранение традиций, адаптация к новым условиям, развитие новых форм искусства и ремесел, основанных на природных материалах."

detailed_impact_europe:
	@echo "Детальное изучение влияния на Европу:  Возможный шок от встречи с совершенно иной культурой, обмен знаниями (в основном, технологиями и знаниями о природе), конкуренция за ресурсы, возможно, конфликты."

detailed_impact_america:
	@echo "Детальное изучение влияния на Америку:  Возможный контакт с уже существующими коренными народами, конкуренция за ресурсы, возможно, конфликты, изменение путей миграции и распространения культур."

# Запуск подцелей
navigation: detailed_navigation
culture: detailed_culture
europe: detailed_impact_europe
america: detailed_impact_america

# Очистка (необязательно)
clean:
	@echo "Очистка Makefile"

# Помощники
help:
	@echo "Makefile для гипотетического сценария: Первая коренная цивилизация, пересекшая Атлантику"
	@echo "Цели:"
	@echo "  all:  Сборка всего сценария"
	@echo "  navigation:  Детальное изучение навигации"
	@echo "  culture:  Детальное изучение культуры"
	@echo "  europe:  Детальное изучение влияния на Европу"
	@echo "  america:  Детальное изучение влияния на Америку"
	@echo "  clean:  Очистка Makefile"
	@echo "  help:  Показать эту справку"
```

